// Hand-written declarations for cities.js, the shared Labs city catalogue generated by SunApp's
// update_cities.py. EclipseTracker's page adds cities.js to the document at run time, the first
// time the city chooser is used (ts/app.ts), as a classic script. It defines two globals on
// globalThis; before it has loaded neither exists, so both are declared as possibly absent.
// A declaration file: never compiled, never served.

import type { City } from './core/citysearch.js';

declare global {
  /** Decoded lazily on first access and cached (so the catalogue is not decoded before it is used). */
  var CITIES: readonly City[] | undefined;
  /** Folds a query the way catalogue names are folded. */
  var foldQuery: ((s: string) => string) | undefined;
}

export {};
